-- La portada de cada programa del catálogo, como clave hacia el origen de medios.
--
-- **Generado desde `program-covers.json`. No editar a mano.**
-- Los checksums de aquí son los bytes que alguien revisó; escribir uno a mano rompería el
-- único vínculo entre lo aprobado y lo que se sirve.
--
-- Correr después de `001_global_training_catalogue.sql`: cada fila referencia un programa
-- que ese archivo crea.
--
-- **Una fila por programa y audiencia.** Hay dos juegos de fotografías, `male` y
-- `female`, y `planning.cover_for` elige el de quien mira; quien prefirió no decirlo ve
-- una mezcla, que es lo que sale cuando el carrusel alterna entre los dos. No hay un
-- tercer juego porque «mixto» no es una fotografía.
--
-- **Actualiza en conflicto**, igual que las demostraciones y por la misma razón: la clave
-- es el contenido, así que un arte nuevo es una dirección nueva, y una fila que se quedara
-- apuntando a la vieja pediría un objeto que el siguiente despliegue ya no lleva.

\set ON_ERROR_STOP on

begin;

create temporary table curated_program_cover (
  program_id uuid,
  audience identity.biological_sex,
  object_key text,
  content_type text,
  width integer,
  height integer,
  byte_size integer,
  checksum text
) on commit drop;


select curated.program_id, curated.audience, curated.object_key, curated.content_type,
       curated.width, curated.height, curated.byte_size, curated.checksum
from curated_program_cover as curated
join planning.programs as target
  on target.id = curated.program_id and target.content_scope = 'global'
on conflict (program_id, audience) do update
set object_key = excluded.object_key,
    content_type = excluded.content_type,
    width = excluded.width,
    height = excluded.height,
    byte_size = excluded.byte_size,
    checksum = excluded.checksum;

commit;
